#nullable enable

using Microsoft.Extensions.DependencyInjection;
using StockFeed.Contracts;
using StockFeed.Landing;
using StockFeed.Slices.StockFeed;
using Marten;
using Shouldly;
using Wolverine;
using Xunit;

namespace StockFeed.IntegrationTests.Slices.StockFeed;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation — which is the only reason these tests mean
/// anything. Pattern: translation. Status: ready. LIVE, so every test here must pass.
///
/// EVERY LANDING MECHANISM MUST SATISFY THESE UNCHANGED, which is what makes the folder a comparison rather than
/// three programs: the rules come from one model, and only the way a notice arrives differs. Nothing in this file
/// mentions a webhook, a table or a clock.
///
/// NOTE WHAT A GIVEN IS HERE, AND HOW IT CHANGED. The foreign notice is never appended to our store, so a GIVEN
/// cannot be "the warehouse told us this" — there is nothing of ours to append for that. A GIVEN is only ever our
/// own <see cref="StockLevelSet"/>: what we previously DECIDED. The arrival of a notice is a message, and a test
/// that wants one sends it.
///
/// The first version of this file appended StockNoticed in its GIVENs, which read naturally and was a symptom of
/// the design being wrong: it asserted a history our system must not have.
/// </summary>
public sealed class TranslateStockNoticeTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static Guid Stream => TranslateStockNoticeState.StreamKey(SeedData.ProductId);

    /// <summary>WHEN the command alone, straight to the decider — a GWT's when= names a COMMAND.</summary>
    private async Task<ApplyOutcome> Apply(Guid noticeId, int onHand, long sequence)
    {
        using var scope = Host.Services.CreateScope();
        var bus = scope.ServiceProvider.GetRequiredService<IMessageBus>();
        return await bus.InvokeAsync<ApplyOutcome>(
            new ApplyStockNotice(SeedData.ProductId, noticeId, onHand, sequence));
    }

    /// <summary>
    /// WHEN the trigger runs: one notice handed to the translator. This is the production path exactly — the only
    /// thing a landing mechanism does is put this message on the bus.
    /// </summary>
    private async Task Deliver(Guid noticeId, int quantity, long sequence)
    {
        using var scope = Host.Services.CreateScope();
        await scope.ServiceProvider.GetRequiredService<IMessageBus>().InvokeAsync(
            new IngestStockNotice(SeedData.ProductId, noticeId, quantity, sequence, SeedData.SeededAt));
    }

    // a notice from the warehouse becomes an event of our own
    //   GIVEN StockNoticed
    //   WHEN  ApplyStockNotice
    //   THEN  StockLevelSet
    [Fact]
    public async Task ANoticeFromTheWarehouseBecomesAnEventOfOurOwn()
    {
        // The GIVEN is the notice, and a notice is a message rather than history — so there is nothing to append
        // and the stream starts empty. That is the model's given="StockNoticed" honoured exactly: the warehouse
        // has told us something. It has not put anything in our event store, because it cannot.
        var outcome = await Apply(SeedData.NoticeId, SeedData.Quantity, SeedData.Sequence);

        outcome.WasApplied.ShouldBeTrue();
        outcome.Rule.ShouldBeNull();

        var events = await EventsFor(Stream);
        events.Length.ShouldBe(1);

        // ONE event, and it is ours. The warehouse's notice is nowhere in our store — which is the single most
        // important assertion in this file, and the whole reason the pattern is called translation.
        var set = events[0].ShouldBeOfType<StockLevelSet>();
        set.NoticeId.ShouldBe(SeedData.NoticeId);
        set.Sequence.ShouldBe(SeedData.Sequence);

        // THE RENAME, asserted. They said quantity=5; our event carries onHand=5. Same value, our word — all
        // mappings= is ever allowed to mean.
        set.OnHand.ShouldBe(SeedData.Quantity);
    }

    // the same notice delivered twice is applied once
    //   GIVEN StockNoticed, StockLevelSet
    //   WHEN  ApplyStockNotice
    //   THEN  error: AlreadyApplied
    [Fact]
    public async Task TheSameNoticeDeliveredTwiceIsAppliedOnce()
    {
        await Given(Stream, SeedData.LevelSet());

        var outcome = await Apply(SeedData.NoticeId, SeedData.Quantity, SeedData.Sequence);

        outcome.WasApplied.ShouldBeFalse();

        // AlreadyApplied and NOT StaleNotice. A redelivery of the notice we last accepted satisfies both
        // conditions and only one is the truth, which is why the decider checks them in that order.
        outcome.Rule.ShouldBe("AlreadyApplied");

        (await EventsFor(Stream)).Length.ShouldBe(1);
    }

    // a notice older than the level we last accepted is refused
    //   GIVEN StockNoticed, StockLevelSet, StockNoticed
    //   WHEN  ApplyStockNotice
    //   THEN  error: StaleNotice
    [Fact]
    public async Task ANoticeOlderThanTheLevelWeLastAcceptedIsRefused()
    {
        // We accepted sequence 7. Now notice 3 arrives — out of order, which nothing across a boundary prevents,
        // and which a webhook or a queue can do even though a cursor-ordered poll cannot.
        await Given(Stream, SeedData.LevelSet());

        var outcome = await Apply(SeedData.LaterNoticeId, SeedData.LaterQuantity, SeedData.StaleSequence);

        outcome.WasApplied.ShouldBeFalse();
        outcome.Rule.ShouldBe("StaleNotice");

        (await EventsFor(Stream)).Length.ShouldBe(1);
    }

    // a notice nobody asks us about becomes our event anyway
    //   GIVEN StockNoticed
    //   THEN  StockLevelSet
    //   (no WHEN: a GIVEN/THEN — the infrastructure half of the slice)
    [Fact]
    public async Task ANoticeNobodyAsksUsAboutBecomesOurEventAnyway()
    {
        // NOBODY ISSUES A COMMAND. The notice is handed to the translator and it decides for itself what command
        // to issue and with what — this test names no command and no onHand, which is the whole difference from
        // the first test in this file.
        await Deliver(SeedData.NoticeId, SeedData.Quantity, SeedData.Sequence);

        var events = await EventsFor(Stream);
        events.Length.ShouldBe(1);
        events[0].ShouldBeOfType<StockLevelSet>().OnHand.ShouldBe(SeedData.Quantity);
    }

    /// <summary>
    /// NOT FROM THE MODEL. At-least-once is the normal case for every landing mechanism, so a redelivery is
    /// ordinary — and this is the test that proves the noticeId on our own event is doing the dedupe work, now
    /// that nothing records the arrivals.
    /// </summary>
    [Fact]
    public async Task DeliveringTheSameNoticeTwiceTranslatesOnce()
    {
        await Deliver(SeedData.NoticeId, SeedData.Quantity, SeedData.Sequence);
        await Deliver(SeedData.NoticeId, SeedData.Quantity, SeedData.Sequence);

        (await EventsFor(Stream)).Length.ShouldBe(1);
    }

    /// <summary>
    /// NOT FROM THE MODEL. A burst of notices for one product, newest last: each is translated, and the level
    /// ends on the newest.
    ///
    /// THIS IS WHERE NOT MATERIALISING THE TODO VIEW COSTS SOMETHING, and it is the honest trade to record. The
    /// first version collapsed a burst to ONE decision, because a per-product row held only the newest notice —
    /// cheaper, and it lost the intermediate levels. An inbox has one entry per message, so every notice is
    /// translated in turn and our stream keeps all of them. For a level feed either is defensible; the inbox
    /// version is more work and more history, and it cannot silently drop a notice, which for a DELTA feed would
    /// be the difference between correct and wrong.
    /// </summary>
    [Fact]
    public async Task ABurstOfNoticesForOneProductEndsOnTheNewest()
    {
        await Deliver(SeedData.NoticeId, SeedData.Quantity, SeedData.Sequence);
        await Deliver(SeedData.LaterNoticeId, SeedData.LaterQuantity, SeedData.LaterSequence);

        var events = await EventsFor(Stream);
        events.Length.ShouldBe(2);

        var set = events[1].ShouldBeOfType<StockLevelSet>();
        set.OnHand.ShouldBe(SeedData.LaterQuantity);
        set.Sequence.ShouldBe(SeedData.LaterSequence);
    }

    /// <summary>
    /// NOT FROM THE MODEL, and the one that guards the boundary in the other direction: a notice arriving out of
    /// order through the real trigger must leave our level alone. The refusal happens in the decider and is
    /// logged by the trigger — there is no todo row quietly absorbing it, which was the first version's way of
    /// making a refusal invisible.
    /// </summary>
    [Fact]
    public async Task AStaleNoticeDeliveredForRealChangesNothing()
    {
        await Deliver(SeedData.NoticeId, SeedData.Quantity, SeedData.Sequence);
        await Deliver(SeedData.LaterNoticeId, 999, SeedData.StaleSequence);

        var events = await EventsFor(Stream);
        events.Length.ShouldBe(1);
        events[0].ShouldBeOfType<StockLevelSet>().OnHand.ShouldBe(SeedData.Quantity);
    }
}
